import { motion } from "framer-motion";
import { Hourglass, Sparkles, BrainCircuit } from "lucide-react";

const mechanisms = [
  {
    icon: Hourglass,
    title: "生命周期",
    subtitle: "Lifecycle",
    desc: "每条书签都有保存期。从收件箱到即将过期，从冷冻库到回收站，让收藏不再静止堆积，而是自然流转。",
    color: "#E8B86D",
  },
  {
    icon: Sparkles,
    title: "随机解冻",
    subtitle: "Unfreeze",
    desc: "冷冻库中的书签会被随机带回视野。像翻开一本旧书，让被遗忘的收藏在某个清晨重新与你相遇。",
    color: "#F4D38A",
  },
  {
    icon: BrainCircuit,
    title: "AI 摘要",
    subtitle: "AI Summary",
    desc: "每条书签自动生成一句话摘要与标签。打开链接前就知道它值不值得看，降低重新面对收藏的判断成本。",
    color: "#7A9CC6",
  },
];

export default function Mechanisms() {
  return (
    <section className="relative py-32 px-6">
      <div className="max-w-6xl mx-auto">
        <motion.div
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: "-100px" }}
          transition={{ duration: 0.8 }}
          className="text-center mb-20"
        >
          <p className="font-display italic text-amber text-lg mb-3 tracking-wide">
            Three Mechanisms
          </p>
          <h2 className="font-display text-4xl md:text-5xl text-parchment font-light mb-6 leading-tight">
            三个机制，让书签<span className="text-flow">重新流动</span>
          </h2>
          <p className="font-serif text-fog max-w-2xl mx-auto leading-relaxed">
            不是让你收藏更多，而是帮你面对已有的收藏——要么读掉，要么归档，要么删除。
          </p>
        </motion.div>

        <div className="grid md:grid-cols-3 gap-6">
          {mechanisms.map((m, i) => {
            const Icon = m.icon;
            return (
              <motion.div
                key={m.title}
                initial={{ opacity: 0, y: 40 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true }}
                transition={{ duration: 0.7, delay: i * 0.15 }}
                className="glass glass-hover rounded-2xl p-8 flex flex-col"
              >
                <div
                  className="w-14 h-14 rounded-xl flex items-center justify-center mb-6 border"
                  style={{
                    borderColor: `${m.color}40`,
                    background: `radial-gradient(circle, ${m.color}1a, transparent)`,
                  }}
                >
                  <Icon className="w-6 h-6" style={{ color: m.color }} />
                </div>

                <div className="mb-2">
                  <span className="font-mono text-xs uppercase tracking-widest" style={{ color: m.color }}>
                    {m.subtitle}
                  </span>
                </div>
                <h3 className="font-display text-3xl text-parchment font-medium mb-4">
                  {m.title}
                </h3>
                <p className="font-serif text-sm text-fog leading-relaxed flex-1">
                  {m.desc}
                </p>

                <div
                  className="mt-6 h-px"
                  style={{
                    background: `linear-gradient(90deg, ${m.color}40, transparent)`,
                  }}
                />
              </motion.div>
            );
          })}
        </div>

        {/* 结尾引言 */}
        <motion.div
          initial={{ opacity: 0 }}
          whileInView={{ opacity: 1 }}
          viewport={{ once: true }}
          transition={{ duration: 1, delay: 0.3 }}
          className="text-center mt-24"
        >
          <div className="divider-flow w-24 mx-auto mb-8" />
          <p className="font-display italic text-2xl md:text-3xl text-fog-light leading-relaxed max-w-3xl mx-auto">
            " 让浏览器书签从杂乱仓库，
            <br />
            变成可流动的知识入口。 "
          </p>
          <p className="font-serif text-xs text-ink-600 mt-6 tracking-widest">
            — Memento 的愿景
          </p>
        </motion.div>
      </div>
    </section>
  );
}
