import Hero from "@/components/landing/Hero";
import PainPoints from "@/components/landing/PainPoints";
import LifecycleFlow from "@/components/landing/LifecycleFlow";
import Mechanisms from "@/components/landing/Mechanisms";
import { Link } from "react-router-dom";
import { motion } from "framer-motion";

function Footer() {
  return (
    <footer className="relative py-16 px-6 border-t border-amber/10">
      <div className="max-w-5xl mx-auto text-center">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.8 }}
        >
          <p className="font-display italic text-amber-light text-xl mb-4">
            准备好让你的书签流动起来了吗？
          </p>
          <Link to="/workspace" className="btn-amber inline-block mb-8">
            打开工作台
          </Link>
          <div className="divider-flow w-32 mx-auto my-6" />
          <p className="font-serif text-xs text-ink-600 tracking-wider">
            Memento · 流光书签 — 一个关于数字囤积的概念 Demo
          </p>
        </motion.div>
      </div>
    </footer>
  );
}

export default function Landing() {
  return (
    <div className="relative">
      <Hero />
      <PainPoints />
      <LifecycleFlow />
      <Mechanisms />
      <Footer />
    </div>
  );
}
