import { motion, AnimatePresence } from "framer-motion";
import { X, Archive, Trash2, RotateCcw, Clock, Calendar, ExternalLink, Sparkles } from "lucide-react";
import { useBookmarkStore } from "@/store/useBookmarkStore";
import { STAGE_META } from "@/types/bookmark";

export default function BookmarkDetail() {
  const { bookmarks, selectedId, closeDetail, moveStage, removeBookmark } = useBookmarkStore();
  const bookmark = bookmarks.find((b) => b.id === selectedId);

  return (
    <AnimatePresence>
      {bookmark && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          onClick={closeDetail}
          className="fixed inset-0 z-50 modal-backdrop flex items-center justify-center p-4 md:p-8"
        >
          <motion.div
            initial={{ opacity: 0, scale: 0.92, y: 20 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.92, y: 20 }}
            transition={{ type: "spring", duration: 0.5 }}
            onClick={(e) => e.stopPropagation()}
            className="glass rounded-2xl max-w-3xl w-full max-h-[88vh] overflow-y-auto"
            style={{ borderColor: "rgba(232,184,109,0.25)" }}
          >
            {/* 封面区 */}
            <div
              className="relative h-40 md:h-48 flex-shrink-0 overflow-hidden rounded-t-2xl"
              style={{ background: bookmark.coverColor }}
            >
              <div className="absolute inset-0 bg-gradient-to-t from-ink-950/80 to-transparent" />
              <div className="absolute bottom-4 left-6 flex items-center gap-3">
                <span className="text-4xl">{bookmark.favicon}</span>
                <span className="font-mono text-xs text-fog-light bg-ink-950/60 px-2 py-1 rounded">
                  {bookmark.domain}
                </span>
              </div>
              <button
                onClick={closeDetail}
                className="absolute top-4 right-4 w-9 h-9 rounded-full bg-ink-950/60 hover:bg-ink-800 flex items-center justify-center text-fog hover:text-parchment transition-all"
              >
                <X className="w-4 h-4" />
              </button>
            </div>

            <div className="p-6 md:p-8">
              {/* 标题 */}
              <h2 className="font-display text-3xl md:text-4xl text-parchment font-light leading-tight mb-4">
                {bookmark.title}
              </h2>

              {/* 元信息 */}
              <div className="flex flex-wrap items-center gap-4 mb-6 font-mono text-xs text-fog-dark">
                <span className="flex items-center gap-1.5">
                  <Calendar className="w-3.5 h-3.5" />
                  收藏于 {bookmark.savedAt}
                </span>
                <span className="flex items-center gap-1.5">
                  <Clock className="w-3.5 h-3.5" />
                  预计阅读 {bookmark.readTimeMin} 分钟
                </span>
                <span
                  className="flex items-center gap-1.5 px-2 py-0.5 rounded"
                  style={{ color: STAGE_META[bookmark.stage].color }}
                >
                  {STAGE_META[bookmark.stage].icon} {STAGE_META[bookmark.stage].label}
                </span>
                {bookmark.isUnfrozen && (
                  <span className="flex items-center gap-1.5 text-amber-light">
                    <Sparkles className="w-3.5 h-3.5" />
                    已解冻
                  </span>
                )}
              </div>

              {/* AI 摘要 */}
              <div className="mb-6">
                <div className="flex items-center gap-2 mb-3">
                  <Sparkles className="w-4 h-4 text-amber" />
                  <span className="font-display italic text-amber text-sm tracking-wide">
                    AI 摘要
                  </span>
                </div>
                <div className="glass rounded-lg p-4 pl-5 border-l-2 border-amber/40">
                  <p className="font-serif text-base text-parchment leading-relaxed">
                    {bookmark.aiSummary}
                  </p>
                </div>
              </div>

              {/* 原文摘录 */}
              <div className="mb-6">
                <span className="font-display italic text-fog text-sm tracking-wide mb-3 block">
                  原文摘录
                </span>
                <p className="font-serif text-sm text-fog leading-relaxed italic pl-4 border-l border-ink-600">
                  {bookmark.excerpt}
                </p>
              </div>

              {/* 标签云 */}
              <div className="mb-8">
                <span className="font-display italic text-fog text-sm tracking-wide mb-3 block">
                  自动标签
                </span>
                <div className="flex flex-wrap gap-2">
                  {bookmark.tags.map((tag) => (
                    <span
                      key={tag}
                      className="px-3 py-1 rounded-md text-sm font-serif text-amber-light bg-amber/10 border border-amber/20"
                    >
                      {tag}
                    </span>
                  ))}
                </div>
              </div>

              {/* 操作按钮 */}
              <div className="flex flex-wrap items-center gap-3 pt-6 border-t border-ink-700/50">
                {bookmark.stage === "trash" ? (
                  <button
                    onClick={() => {
                      moveStage(bookmark.id, "inbox");
                      closeDetail();
                    }}
                    className="flex items-center gap-2 px-5 py-2.5 rounded-lg bg-amber/15 hover:bg-amber/25 border border-amber/40 text-amber-light font-serif text-sm transition-all"
                  >
                    <RotateCcw className="w-4 h-4" />
                    恢复到收件箱
                  </button>
                ) : (
                  <>
                    {bookmark.stage !== "freezer" && (
                      <button
                        onClick={() => {
                          moveStage(bookmark.id, "freezer");
                          closeDetail();
                        }}
                        className="flex items-center gap-2 px-5 py-2.5 rounded-lg bg-ink-800 hover:bg-ink-700 border border-ink-600 text-fog hover:text-parchment font-serif text-sm transition-all"
                      >
                        <Archive className="w-4 h-4" />
                        归档到冷冻库
                      </button>
                    )}
                    <button
                      onClick={() => {
                        moveStage(bookmark.id, "trash");
                        closeDetail();
                      }}
                      className="flex items-center gap-2 px-5 py-2.5 rounded-lg bg-ink-800 hover:bg-red-500/15 border border-ink-600 hover:border-red-500/40 text-fog hover:text-red-400 font-serif text-sm transition-all"
                    >
                      <Trash2 className="w-4 h-4" />
                      移到回收站
                    </button>
                  </>
                )}
                <a
                  href={bookmark.url}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="ml-auto flex items-center gap-2 px-5 py-2.5 rounded-lg bg-amber text-ink-950 hover:bg-amber-light font-serif text-sm font-medium transition-all"
                >
                  <ExternalLink className="w-4 h-4" />
                  阅读原文
                </a>
              </div>
            </div>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}
