import { motion } from "framer-motion";
import { STAGE_META } from "@/types/bookmark";
import type { LifecycleStage } from "@/types/bookmark";

const stages: LifecycleStage[] = ["inbox", "expiring", "freezer", "trash"];

const flowDescriptions: Record<LifecycleStage, string> = {
  inbox: "新建收藏进入收件箱，设定保存期",
  expiring: "临近过期，提醒你做决定",
  freezer: "归档冷藏，等待随机解冻",
  trash: "即将被彻底清理，释放空间",
};

export default function LifecycleFlow() {
  return (
    <section className="relative py-32 px-6">
      <div className="max-w-6xl mx-auto">
        <motion.div
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: "-100px" }}
          transition={{ duration: 0.8 }}
          className="text-center mb-20"
        >
          <p className="font-display italic text-amber text-lg mb-3 tracking-wide">
            The Lifecycle
          </p>
          <h2 className="font-display text-4xl md:text-5xl text-parchment font-light mb-6 leading-tight">
            书签也有<span className="text-flow">生命周期</span>
          </h2>
          <p className="font-serif text-fog max-w-2xl mx-auto leading-relaxed">
            每一条收藏都不是静止的。它们有自己的旅程——从被看见，到被决定，到被沉淀或被放下。
          </p>
        </motion.div>

        {/* 流程图 */}
        <div className="relative">
          {/* 连接线 */}
          <div className="hidden md:block absolute top-[42px] left-[12%] right-[12%] h-px">
            <div className="divider-flow w-full h-full" />
          </div>

          <div className="grid grid-cols-2 md:grid-cols-4 gap-8 md:gap-4 relative">
            {stages.map((stage, i) => {
              const meta = STAGE_META[stage];
              return (
                <motion.div
                  key={stage}
                  initial={{ opacity: 0, y: 30 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  viewport={{ once: true }}
                  transition={{ duration: 0.6, delay: i * 0.2 }}
                  className="flex flex-col items-center text-center"
                >
                  {/* 节点 */}
                  <div className="relative mb-6">
                    <div
                      className="w-20 h-20 rounded-full flex items-center justify-center text-3xl border-2 relative z-10"
                      style={{
                        borderColor: meta.color,
                        background: `radial-gradient(circle, ${meta.color}22, transparent 70%)`,
                        boxShadow: `0 0 30px ${meta.color}33`,
                      }}
                    >
                      {meta.icon}
                    </div>
                    <div
                      className="absolute inset-0 rounded-full animate-breathe"
                      style={{
                        background: `radial-gradient(circle, ${meta.color}22, transparent 70%)`,
                        filter: "blur(12px)",
                      }}
                    />
                  </div>

                  <h3
                    className="font-display text-2xl font-medium mb-2"
                    style={{ color: meta.color }}
                  >
                    {meta.label}
                  </h3>
                  <p className="font-serif text-xs text-fog leading-relaxed max-w-[180px]">
                    {flowDescriptions[stage]}
                  </p>

                  {/* 序号 */}
                  <span className="font-mono text-xs text-ink-600 mt-4">
                    0{i + 1}
                  </span>
                </motion.div>
              );
            })}
          </div>
        </div>

        {/* 随机解冻说明 */}
        <motion.div
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.8, delay: 0.4 }}
          className="mt-16 flex items-center justify-center"
        >
          <div className="glass rounded-full px-6 py-3 flex items-center gap-3">
            <span className="text-lg">🧊</span>
            <span className="font-serif text-sm text-fog">冷冻库</span>
            <span className="font-display italic text-amber text-sm">→ 随机解冻 →</span>
            <span className="font-serif text-sm text-fog">重新回到视野</span>
            <span className="text-lg">✨</span>
          </div>
        </motion.div>
      </div>
    </section>
  );
}
