import { Link, useLocation } from "react-router-dom";
import { BookMarked } from "lucide-react";

export default function Nav() {
  const { pathname } = useLocation();
  const isWorkspace = pathname === "/workspace";

  return (
    <nav className="fixed top-0 left-0 right-0 z-40">
      <div className="glass border-x-0 border-t-0">
        <div className="max-w-7xl mx-auto px-6 md:px-10 h-16 flex items-center justify-between">
          <Link to="/" className="flex items-center gap-3 group">
            <span className="relative">
              <BookMarked className="w-5 h-5 text-amber transition-transform group-hover:scale-110" />
              <span className="absolute -top-1 -right-1 w-1.5 h-1.5 rounded-full bg-amber-light animate-breathe" />
            </span>
            <span className="font-display text-xl tracking-wide text-parchment">
              Memento
            </span>
            <span className="hidden sm:inline font-serif text-xs text-fog-dark tracking-widest">
              流光书签
            </span>
          </Link>

          <div className="flex items-center gap-2">
            <Link
              to="/"
              className={`px-4 py-1.5 text-sm font-serif tracking-wide transition-colors ${
                !isWorkspace ? "text-amber-light" : "text-fog hover:text-parchment"
              }`}
            >
              概念
            </Link>
            <span className="text-ink-600">·</span>
            <Link
              to="/workspace"
              className={`px-4 py-1.5 text-sm font-serif tracking-wide transition-colors ${
                isWorkspace ? "text-amber-light" : "text-fog hover:text-parchment"
              }`}
            >
              工作台
            </Link>
          </div>
        </div>
      </div>
    </nav>
  );
}
