import { Link } from "react-router-dom";
import { motion } from "framer-motion";
import { ArrowDown, Sparkles } from "lucide-react";

export default function Hero() {
  return (
    <section className="relative min-h-screen flex items-center justify-center px-6 pt-16">
      <div className="max-w-5xl mx-auto text-center relative z-10">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 1, delay: 0.2 }}
          className="inline-flex items-center gap-2 px-4 py-1.5 mb-8 rounded-full border border-amber/30 bg-amber/5"
        >
          <Sparkles className="w-3.5 h-3.5 text-amber" />
          <span className="font-serif text-xs tracking-[0.2em] text-amber-light">
            AI 驱动的书签生命周期管理
          </span>
        </motion.div>

        <motion.h1
          initial={{ opacity: 0, y: 30 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 1.2, delay: 0.4 }}
          className="font-display text-7xl md:text-8xl lg:text-9xl font-light leading-none mb-4"
        >
          <span className="text-flow">Memento</span>
        </motion.h1>

        <motion.p
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ duration: 1, delay: 0.8 }}
          className="font-display italic text-2xl md:text-3xl text-fog-light mb-2 tracking-wide"
        >
          流光书签
        </motion.p>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 1, delay: 1 }}
          className="divider-flow w-32 mx-auto my-8"
        />

        <motion.p
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 1, delay: 1.1 }}
          className="font-serif text-lg md:text-xl text-fog leading-relaxed max-w-2xl mx-auto mb-3"
        >
          收藏从未停止，学习从未开始。
        </motion.p>
        <motion.p
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 1, delay: 1.3 }}
          className="font-serif text-lg md:text-xl text-fog leading-relaxed max-w-2xl mx-auto mb-12"
        >
          与其让你收藏的好内容沉睡在信息黑洞里，
          <br className="hidden md:block" />
          不如让书签流动起来——被看见，被消费，被沉淀。
        </motion.p>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 1, delay: 1.5 }}
          className="flex flex-col sm:flex-row items-center justify-center gap-5"
        >
          <Link to="/workspace" className="btn-amber inline-block">
            进入工作台
          </Link>
          <a
            href="#pain"
            className="font-serif text-sm text-fog hover:text-amber-light transition-colors flex items-center gap-2"
          >
            <ArrowDown className="w-3.5 h-3.5 animate-bounce" />
            了解理念
          </a>
        </motion.div>
      </div>

      {/* 底部渐隐 */}
      <div className="absolute bottom-0 left-0 right-0 h-32 bg-gradient-to-t from-ink-950 to-transparent pointer-events-none" />
    </section>
  );
}
