import { motion, AnimatePresence } from "framer-motion";
import { useBookmarkStore } from "@/store/useBookmarkStore";
import { STAGE_META } from "@/types/bookmark";
import StatsBar from "@/components/workspace/StatsBar";
import UnfreezeCard from "@/components/workspace/UnfreezeCard";
import StageTabs from "@/components/workspace/StageTabs";
import BookmarkCard from "@/components/workspace/BookmarkCard";
import BookmarkDetail from "@/components/workspace/BookmarkDetail";
import { Snowflake } from "lucide-react";

export default function Workspace() {
  const { bookmarks, activeStage } = useBookmarkStore();
  const filtered = bookmarks.filter((b) => b.stage === activeStage);
  const meta = STAGE_META[activeStage];

  return (
    <div className="relative min-h-screen pt-24 pb-20 px-6">
      <div className="max-w-6xl mx-auto">
        {/* 标题区 */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
          className="mb-8"
        >
          <p className="font-display italic text-amber text-sm tracking-wide mb-2">
            Workspace
          </p>
          <h1 className="font-display text-4xl md:text-5xl text-parchment font-light mb-3">
            书签工作台
          </h1>
          <p className="font-serif text-fog text-sm max-w-xl leading-relaxed">
            面对你的收藏。每一条都在等待你的决定——读掉、归档，或是放下。
          </p>
        </motion.div>

        {/* 统计栏 */}
        <div className="mb-8">
          <StatsBar />
        </div>

        {/* 随机解冻 */}
        <div className="mb-8">
          <UnfreezeCard />
        </div>

        {/* 阶段标签 */}
        <div className="mb-6 flex items-center justify-between flex-wrap gap-4">
          <StageTabs />
        </div>

        {/* 阶段描述 */}
        <motion.div
          key={activeStage}
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.4 }}
          className="mb-6 flex items-center gap-2"
        >
          <span className="text-lg">{meta.icon}</span>
          <span className="font-display text-lg" style={{ color: meta.color }}>
            {meta.label}
          </span>
          <span className="font-serif text-sm text-fog-dark">· {meta.desc}</span>
          <span className="ml-auto font-mono text-xs text-fog-dark">
            {filtered.length} 条
          </span>
        </motion.div>

        {/* 书签列表 */}
        {filtered.length > 0 ? (
          <div className="grid md:grid-cols-2 gap-4">
            <AnimatePresence mode="popLayout">
              {filtered.map((b, i) => (
                <BookmarkCard key={b.id} bookmark={b} index={i} />
              ))}
            </AnimatePresence>
          </div>
        ) : (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            className="glass rounded-2xl py-20 text-center"
          >
            <Snowflake className="w-10 h-10 text-ink-600 mx-auto mb-4" />
            <p className="font-display italic text-fog text-lg">
              这里很安静
            </p>
            <p className="font-serif text-sm text-fog-dark mt-2">
              没有书签在这个阶段。去其他阶段看看吧。
            </p>
          </motion.div>
        )}
      </div>

      {/* 详情弹层 */}
      <BookmarkDetail />
    </div>
  );
}
