import { create } from "zustand";
import type { Bookmark, LifecycleStage } from "@/types/bookmark";
import { mockBookmarks } from "@/data/mockBookmarks";

interface BookmarkStore {
  bookmarks: Bookmark[];
  activeStage: LifecycleStage;
  selectedId: string | null;
  setActiveStage: (stage: LifecycleStage) => void;
  openDetail: (id: string) => void;
  closeDetail: () => void;
  moveStage: (id: string, stage: LifecycleStage) => void;
  removeBookmark: (id: string) => void;
  unfreeze: (id: string) => void;
}

export const useBookmarkStore = create<BookmarkStore>((set) => ({
  bookmarks: mockBookmarks,
  activeStage: "inbox",
  selectedId: null,
  setActiveStage: (stage) => set({ activeStage: stage }),
  openDetail: (id) => set({ selectedId: id }),
  closeDetail: () => set({ selectedId: null }),
  moveStage: (id, stage) =>
    set((state) => ({
      bookmarks: state.bookmarks.map((b) =>
        b.id === id ? { ...b, stage, isUnfrozen: stage === "expiring" ? b.isUnfrozen : false } : b
      ),
    })),
  removeBookmark: (id) =>
    set((state) => ({
      bookmarks: state.bookmarks.filter((b) => b.id !== id),
      selectedId: state.selectedId === id ? null : state.selectedId,
    })),
  unfreeze: (id) =>
    set((state) => ({
      bookmarks: state.bookmarks.map((b) =>
        b.id === id ? { ...b, stage: "expiring" as LifecycleStage, isUnfrozen: true, daysRemaining: 7 } : b
      ),
    })),
}));
