import { useBookmarkStore } from "@/store/useBookmarkStore";
import { STAGE_META } from "@/types/bookmark";
import type { LifecycleStage } from "@/types/bookmark";

const stages: LifecycleStage[] = ["inbox", "expiring", "freezer", "trash"];

export default function StageTabs() {
  const { bookmarks, activeStage, setActiveStage } = useBookmarkStore();

  return (
    <div className="flex flex-wrap items-center gap-2">
      {stages.map((stage) => {
        const meta = STAGE_META[stage];
        const count = bookmarks.filter((b) => b.stage === stage).length;
        const active = activeStage === stage;
        return (
          <button
            key={stage}
            onClick={() => setActiveStage(stage)}
            data-active={active}
            className="stage-pill flex items-center gap-2 px-4 py-2 rounded-full border border-ink-600 text-fog font-serif text-sm hover:text-parchment"
            style={
              active
                ? { borderColor: "transparent" }
                : {}
            }
          >
            <span className="text-sm">{meta.icon}</span>
            <span>{meta.label}</span>
            <span className="font-mono text-xs opacity-70">{count}</span>
          </button>
        );
      })}
    </div>
  );
}
