import { motion } from "framer-motion";

const stats = [
  { value: "3,847", label: "收藏总数", desc: "平均每个人的书签栏" },
  { value: "11%", label: "会被再次打开", desc: "接近九成收藏永久沉睡" },
  { value: "0", label: "主动整理次数", desc: "整理成本越来越高，最后放弃" },
];

export default function PainPoints() {
  return (
    <section id="pain" className="relative py-32 px-6">
      <div className="max-w-5xl mx-auto">
        <motion.div
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: "-100px" }}
          transition={{ duration: 0.8 }}
          className="text-center mb-20"
        >
          <p className="font-display italic text-amber text-lg mb-3 tracking-wide">
            The Information Black Hole
          </p>
          <h2 className="font-display text-4xl md:text-5xl text-parchment font-light mb-6 leading-tight">
            只进不出的<span className="text-flow">信息黑洞</span>
          </h2>
          <p className="font-serif text-fog max-w-2xl mx-auto leading-relaxed">
            你也有过这样的时刻吗——看到好文章先收藏，收藏之后再没打开。
            <br />
            真正有价值的内容被埋在几千个链接里，整理成本越来越高，最后反而不想再看。
          </p>
        </motion.div>

        <div className="grid md:grid-cols-3 gap-6 mb-16">
          {stats.map((s, i) => (
            <motion.div
              key={s.label}
              initial={{ opacity: 0, y: 30 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.8, delay: i * 0.15 }}
              className="glass glass-hover rounded-xl p-8 text-center"
            >
              <div className="font-mono text-5xl md:text-6xl font-light text-amber-light mb-3">
                {s.value}
              </div>
              <div className="font-serif text-parchment text-lg mb-1">{s.label}</div>
              <div className="font-serif text-xs text-fog-dark">{s.desc}</div>
            </motion.div>
          ))}
        </div>

        {/* 收藏 vs 阅读对比条 */}
        <motion.div
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.8 }}
          className="glass rounded-xl p-8 md:p-10"
        >
          <div className="mb-8">
            <div className="flex justify-between items-end mb-2">
              <span className="font-serif text-sm text-fog-light">收藏速率</span>
              <span className="font-mono text-amber-light text-sm">持续增长 ↗</span>
            </div>
            <div className="h-3 rounded-full bg-ink-800 overflow-hidden">
              <motion.div
                initial={{ width: 0 }}
                whileInView={{ width: "100%" }}
                viewport={{ once: true }}
                transition={{ duration: 1.5, ease: "easeOut" }}
                className="h-full rounded-full bg-gradient-to-r from-amber-deep via-amber to-amber-glow"
              />
            </div>
          </div>
          <div>
            <div className="flex justify-between items-end mb-2">
              <span className="font-serif text-sm text-fog-light">消费速率</span>
              <span className="font-mono text-fog-dark text-sm">几乎停滞 →</span>
            </div>
            <div className="h-3 rounded-full bg-ink-800 overflow-hidden">
              <motion.div
                initial={{ width: 0 }}
                whileInView={{ width: "11%" }}
                viewport={{ once: true }}
                transition={{ duration: 1.5, ease: "easeOut", delay: 0.3 }}
                className="h-full rounded-full bg-gradient-to-r from-ink-600 to-fog-dark"
              />
            </div>
          </div>
          <p className="font-display italic text-center text-fog mt-8 text-lg leading-relaxed">
            " 收藏给人一种'我已经拥有了它'的错觉，
            <br />
            但拥有不等于理解，保存不等于消化。 "
          </p>
        </motion.div>
      </div>
    </section>
  );
}
