import { motion } from "framer-motion";
import { Archive, Trash2, RotateCcw, Clock, ExternalLink } from "lucide-react";
import type { Bookmark } from "@/types/bookmark";
import { useBookmarkStore } from "@/store/useBookmarkStore";

interface Props {
  bookmark: Bookmark;
  index: number;
}

export default function BookmarkCard({ bookmark, index }: Props) {
  const { openDetail, moveStage, removeBookmark } = useBookmarkStore();

  const totalDays = 30;
  const pct = Math.max(0, Math.min(100, (bookmark.daysRemaining / totalDays) * 100));
  const circumference = 2 * Math.PI * 18;
  const offset = circumference - (pct / 100) * circumference;

  const handleArchive = (e: React.MouseEvent) => {
    e.stopPropagation();
    moveStage(bookmark.id, "freezer");
  };
  const handleDelete = (e: React.MouseEvent) => {
    e.stopPropagation();
    moveStage(bookmark.id, "trash");
  };
  const handleRestore = (e: React.MouseEvent) => {
    e.stopPropagation();
    moveStage(bookmark.id, "inbox");
  };

  return (
    <motion.div
      layout
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, scale: 0.9 }}
      transition={{ duration: 0.4, delay: index * 0.05 }}
      onClick={() => openDetail(bookmark.id)}
      className="glass glass-hover rounded-xl p-5 cursor-pointer group"
    >
      {/* 顶部：封面 + 域名 */}
      <div className="flex items-start gap-3 mb-4">
        <div
          className="w-11 h-11 rounded-lg flex items-center justify-center text-lg flex-shrink-0"
          style={{ background: bookmark.coverColor }}
        >
          {bookmark.favicon}
        </div>
        <div className="flex-1 min-w-0">
          <h3 className="font-display text-lg text-parchment leading-snug mb-1 line-clamp-2 group-hover:text-amber-light transition-colors">
            {bookmark.title}
          </h3>
          <div className="flex items-center gap-2">
            <span className="font-mono text-xs text-fog-dark">{bookmark.domain}</span>
            <span className="text-ink-600">·</span>
            <span className="font-mono text-xs text-fog-dark flex items-center gap-1">
              <Clock className="w-3 h-3" />
              {bookmark.readTimeMin}min
            </span>
          </div>
        </div>

        {/* 剩余天数环 */}
        <div className="relative w-12 h-12 flex-shrink-0">
          <svg className="progress-ring w-12 h-12" viewBox="0 0 40 40">
            <circle
              cx="20"
              cy="20"
              r="18"
              fill="none"
              stroke="rgba(232,184,109,0.1)"
              strokeWidth="2"
            />
            <circle
              cx="20"
              cy="20"
              r="18"
              fill="none"
              stroke={bookmark.daysRemaining < 0 ? "#6E7681" : "#E8B86D"}
              strokeWidth="2"
              strokeLinecap="round"
              strokeDasharray={circumference}
              strokeDashoffset={offset}
            />
          </svg>
          <div className="absolute inset-0 flex items-center justify-center">
            <span
              className={`font-mono text-xs ${
                bookmark.daysRemaining < 0
                  ? "text-fog-dark"
                  : bookmark.daysRemaining <= 3
                  ? "text-amber-glow"
                  : "text-amber-light"
              }`}
            >
              {bookmark.daysRemaining < 0
                ? "过期"
                : `${bookmark.daysRemaining}d`}
            </span>
          </div>
        </div>
      </div>

      {/* AI 摘要 */}
      <div className="mb-4 pl-3 border-l-2 border-amber/20">
        <p className="font-serif text-sm text-fog leading-relaxed line-clamp-2">
          {bookmark.aiSummary}
        </p>
      </div>

      {/* 标签 */}
      <div className="flex flex-wrap gap-1.5 mb-4">
        {bookmark.tags.map((tag) => (
          <span
            key={tag}
            className="px-2 py-0.5 rounded text-xs font-serif text-fog bg-ink-800/60"
          >
            {tag}
          </span>
        ))}
      </div>

      {/* 操作栏 */}
      <div className="flex items-center gap-2 pt-3 border-t border-ink-700/50">
        {bookmark.stage === "trash" ? (
          <button
            onClick={handleRestore}
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-md text-xs font-serif text-fog hover:text-amber-light hover:bg-amber/10 transition-all"
          >
            <RotateCcw className="w-3 h-3" />
            恢复
          </button>
        ) : (
          <>
            {bookmark.stage !== "freezer" && (
              <button
                onClick={handleArchive}
                className="flex items-center gap-1.5 px-3 py-1.5 rounded-md text-xs font-serif text-fog hover:text-amber-light hover:bg-amber/10 transition-all"
              >
                <Archive className="w-3 h-3" />
                归档
              </button>
            )}
            <button
              onClick={handleDelete}
              className="flex items-center gap-1.5 px-3 py-1.5 rounded-md text-xs font-serif text-fog hover:text-red-400 hover:bg-red-500/10 transition-all"
            >
              <Trash2 className="w-3 h-3" />
              {bookmark.stage === "freezer" ? "删除" : "移除"}
            </button>
          </>
        )}
        <a
          href={bookmark.url}
          target="_blank"
          rel="noopener noreferrer"
          onClick={(e) => e.stopPropagation()}
          className="ml-auto flex items-center gap-1.5 px-3 py-1.5 rounded-md text-xs font-serif text-amber hover:bg-amber/10 transition-all"
        >
          <ExternalLink className="w-3 h-3" />
          打开
        </a>
      </div>
    </motion.div>
  );
}
