import { useBookmarkStore } from "@/store/useBookmarkStore";
import { Inbox, Hourglass, Snowflake, Recycle } from "lucide-react";
import type { LifecycleStage } from "@/types/bookmark";
import { motion } from "framer-motion";

const statConfig: {
  stage: LifecycleStage;
  icon: typeof Inbox;
  label: string;
}[] = [
  { stage: "inbox", icon: Inbox, label: "收件箱" },
  { stage: "expiring", icon: Hourglass, label: "即将过期" },
  { stage: "freezer", icon: Snowflake, label: "冷冻库" },
  { stage: "trash", icon: Recycle, label: "回收站" },
];

export default function StatsBar() {
  const { bookmarks, setActiveStage } = useBookmarkStore();
  const total = bookmarks.length;

  return (
    <div className="grid grid-cols-2 md:grid-cols-4 gap-3 md:gap-4">
      {statConfig.map((cfg, i) => {
        const Icon = cfg.icon;
        const count = bookmarks.filter((b) => b.stage === cfg.stage).length;
        const pct = total > 0 ? Math.round((count / total) * 100) : 0;
        return (
          <motion.button
            key={cfg.stage}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, delay: i * 0.08 }}
            onClick={() => setActiveStage(cfg.stage)}
            className="glass glass-hover rounded-xl p-5 text-left cursor-pointer"
          >
            <div className="flex items-center justify-between mb-3">
              <Icon className="w-4 h-4 text-amber" />
              <span className="font-serif text-xs text-fog-dark">{cfg.label}</span>
            </div>
            <div className="font-mono text-3xl md:text-4xl font-light text-parchment mb-2">
              {count}
            </div>
            <div className="h-1 rounded-full bg-ink-800 overflow-hidden">
              <div
                className="h-full rounded-full bg-gradient-to-r from-amber-deep to-amber transition-all duration-700"
                style={{ width: `${pct}%` }}
              />
            </div>
          </motion.button>
        );
      })}
    </div>
  );
}
