import { useBookmarkStore } from "@/store/useBookmarkStore";
import { motion, AnimatePresence } from "framer-motion";
import { Sparkles, RotateCcw, Trash2, X } from "lucide-react";

export default function UnfreezeCard() {
  const { bookmarks, unfreeze, removeBookmark } = useBookmarkStore();
  const unfrozen = bookmarks.find((b) => b.isUnfrozen && b.stage !== "trash");

  return (
    <AnimatePresence mode="wait">
      {unfrozen && (
        <motion.div
          key={unfrozen.id}
          initial={{ opacity: 0, scale: 0.95, y: -10 }}
          animate={{ opacity: 1, scale: 1, y: 0 }}
          exit={{ opacity: 0, scale: 0.95, y: -10 }}
          transition={{ duration: 0.5 }}
          className="relative rounded-2xl overflow-hidden"
          style={{
            background: "linear-gradient(135deg, rgba(232,184,109,0.08), rgba(14,17,23,0.6))",
            border: "1px solid rgba(232,184,109,0.3)",
            boxShadow: "0 0 40px rgba(232,184,109,0.12)",
          }}
        >
          {/* 呼吸光晕 */}
          <div
            className="absolute -top-20 -right-20 w-60 h-60 rounded-full animate-breathe pointer-events-none"
            style={{
              background: "radial-gradient(circle, rgba(255,216,155,0.25), transparent 70%)",
              filter: "blur(30px)",
            }}
          />

          <div className="relative p-6 md:p-7">
            <div className="flex items-center gap-2 mb-4">
              <Sparkles className="w-4 h-4 text-amber-light" />
              <span className="font-display italic text-amber-light text-sm tracking-wide">
                今日重见 · Today's Rediscovery
              </span>
              <span className="ml-auto font-mono text-xs text-fog-dark">
                从冷冻库浮现
              </span>
            </div>

            <div className="flex items-start gap-4 mb-4">
              <div
                className="w-12 h-12 rounded-lg flex items-center justify-center text-xl flex-shrink-0"
                style={{ background: unfrozen.coverColor }}
              >
                {unfrozen.favicon}
              </div>
              <div className="flex-1 min-w-0">
                <h3 className="font-display text-xl text-parchment mb-1 truncate">
                  {unfrozen.title}
                </h3>
                <p className="font-mono text-xs text-fog-dark">{unfrozen.domain}</p>
              </div>
            </div>

            <p className="font-serif text-sm text-fog leading-relaxed mb-5 pl-1 border-l-2 border-amber/30 pl-4">
              {unfrozen.aiSummary}
            </p>

            <div className="flex flex-wrap items-center gap-3">
              <button
                onClick={() => unfreeze(unfrozen.id)}
                className="flex items-center gap-2 px-4 py-2 rounded-lg bg-amber/15 hover:bg-amber/25 border border-amber/40 text-amber-light font-serif text-sm transition-all"
              >
                <RotateCcw className="w-3.5 h-3.5" />
                重新激活
              </button>
              <button
                onClick={() => removeBookmark(unfrozen.id)}
                className="flex items-center gap-2 px-4 py-2 rounded-lg bg-ink-800 hover:bg-ink-700 border border-ink-600 text-fog hover:text-parchment font-serif text-sm transition-all"
              >
                <Trash2 className="w-3.5 h-3.5" />
                彻底放下
              </button>
              <div className="ml-auto flex items-center gap-2 flex-wrap">
                {unfrozen.tags.slice(0, 3).map((tag) => (
                  <span
                    key={tag}
                    className="px-2.5 py-1 rounded-md text-xs font-serif text-fog bg-ink-800/60"
                  >
                    {tag}
                  </span>
                ))}
              </div>
            </div>
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}
